import itertools
import numpy as np
def _run(fn, *args):
    return fn(*[v.copy() if isinstance(v, np.ndarray) else v for v in args])
def _lattice(shape, spacing, horizon):
    g = np.array(list(itertools.product(*[range(n) for n in shape])), dtype=float)
    X = spacing * g
    d = X[None, :, :] - X[:, None, :]
    r = np.sqrt(np.sum(d * d, axis=2))
    a, b = np.nonzero((r > 0.0) & (r <= horizon))
    return X, a, b, (1.0 - r[a, b] / horizon) ** 2 + 0.1
def _mats(result):
    K, F = (np.asarray(m, dtype=float) for m in result)
    assert K.shape == F.shape and K.ndim == 3 and K.shape[1:] == (3, 3)
    return np.concatenate([K.ravel() / 100.0, F.ravel()])
def _warp(X):
    return X + 0.04 * np.stack([np.sin(X[:, 1] + 0.3 * X[:, 2]), X[:, 0] * X[:, 2] / 5.0,
                               np.cos(0.8 * X[:, 0]) - 0.5 * X[:, 1] ** 2 / 4.0], axis=1)
X, a, b, w = _lattice((3, 3, 3), 1.0, 1.8)
cut = ((X[a, 1] <= 1.0) & (X[b, 1] >= 2.0)) | ((X[b, 1] <= 1.0) & (X[a, 1] >= 2.0))
h = np.where(cut, 0.05, 1.0) * (1.0 - 0.3 * (X[b, 0] > X[a, 0]))
assert np.allclose(_mats(_run(assemble_nodal_deformation_gradients, X, _warp(X), a, b, w, np.ones(a.size), 1.0)), target)

